function longestWithKKinds(s: string, k: number): number {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    const seen = new Set<string>();
    for (let j = i; j < s.length; j++) {
      seen.add(s[j]);
      if (seen.size > k) break;
      best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

