function longestWithKKinds(s: string, k: number): number {
  const count = new Map<string, number>();
  let left = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    count.set(s[right], (count.get(s[right]) ?? 0) + 1);
    while (count.size > k) {
      const c = s[left++], v = count.get(c)! - 1;
      if (v === 0) count.delete(c); else count.set(c, v);
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

